<?php

namespace Tests\Feature;

use App\Models\Department;
use App\Models\Organization;
use App\Models\User;
use App\Support\Pages;
use App\Support\Tenant;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

/**
 * D-266: the page registry follows KK_FARMS_RBAC.md §8.3. tests/Feature/rbac/spec_pages.json holds the spec's marks per
 * registry page (generated by docs/decisions/D-261/scripts/spec_matrix.py; a page shared by several menus takes the most
 * generous row, S-1). Every difference between the registry and the spec must be listed, with its reason, in
 * tests/Feature/rbac/spec_exceptions.json: so a new difference fails here, and a fixed one must be removed from the list.
 * Regenerate the list on purpose with: RBAC_SPEC_WRITE=1 php artisan test tests/Feature/SpecMatrixTest.php (then write the reasons).
 */
class SpecMatrixTest extends TestCase
{
    use RefreshDatabase;

    private const ROLES = ['ceo', 'manager', 'vet', 'caretaker', 'feeding', 'cleaning', 'finance'];

    public function test_the_page_registry_matches_the_spec_except_where_an_exception_says_why(): void
    {
        $org = Organization::create(['name' => 'Spec Farm', 'slug' => 'spec-farm']);
        Tenant::set($org->id);
        Department::seedDefaults((string) $org->id);
        $users = [];
        foreach (self::ROLES as $role) {
            $users[$role] = User::create(['name' => $role, 'email' => "$role@spec.test", 'password' => 'x', 'role' => $role, 'org_id' => $org->id, 'active' => true]);
        }
        $spec = json_decode(file_get_contents(__DIR__.'/rbac/spec_pages.json'), true);
        $diffs = [];
        foreach ($spec as $key => $marks) {
            if (str_starts_with($key, 'fodder.') || ! isset(Pages::registry()[$key])) {
                continue; // the optional Fodder app is off by default (F-29)
            }
            foreach (self::ROLES as $role) {
                $open = Pages::allowsKey($users[$role], $key);
                if ($open !== (bool) $marks[$role]) {
                    $diffs["$key|$role"] = $open ? 'over' : 'under';
                }
            }
        }
        ksort($diffs);
        $file = __DIR__.'/rbac/spec_exceptions.json';
        if (env('RBAC_SPEC_WRITE')) {
            $old = is_file($file) ? json_decode(file_get_contents($file), true) : [];
            file_put_contents($file, json_encode(array_map(fn ($d, $k) => ['direction' => $d, 'reason' => $old[$k]['reason'] ?? 'TODO'], $diffs, array_keys($diffs)) ? array_combine(array_keys($diffs), array_map(fn ($d, $k) => ['direction' => $d, 'reason' => $old[$k]['reason'] ?? 'TODO'], $diffs, array_keys($diffs))) : [], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)."\n");
            $this->markTestSkipped('Exceptions written: '.count($diffs));
        }
        $exceptions = json_decode(file_get_contents($file), true);
        $this->assertSame([], array_keys(array_diff_key($diffs, $exceptions)), 'Registry differs from the spec and is not listed in spec_exceptions.json');
        $this->assertSame([], array_keys(array_diff_key($exceptions, $diffs)), 'Listed as an exception but the registry now matches the spec: remove it from spec_exceptions.json');
        $todo = array_keys(array_filter($exceptions, fn ($e) => trim($e['reason']) === '' || $e['reason'] === 'TODO'));
        $this->assertSame([], $todo, 'Every exception needs a reason');
    }
}
